import * as T from './vendor/three.module.js';
const ease=v=>{const t=Math.max(0,Math.min(1,v));return t*t*t*(t*(t*6-15)+10);};
// A single programme lift and return, with continuous zero-speed joins and a stable quiet pose.
export function ticketPose(time,reduced=false,rest){const t=Number.isFinite(time)?Math.max(0,time):0,lift=reduced?0:ease(t/.9)*(1-ease((t-2)/1)),reach=reduced?1:ease(t/.75),hands=[-1,1].map((sign,i)=>{const a=rest?.[i]||{x:sign*8,y:24,z:2},b={x:sign*3.4,y:29+lift*5,z:12+lift};return {x:a.x+(b.x-a.x)*reach,y:a.y+(b.y-a.y)*reach,z:a.z+(b.z-a.z)*reach};});return {reach,lift,hands};}
export function createTicket(w){const g=new T.Group(),paper=w.mat('#eadcba',{roughness:.92}),ink=w.mat('#557064');w.mesh(new T.BoxGeometry(6.4,3.2,.12),paper,g);for(const x of[-2.4,2.4]){const strip=w.mesh(new T.BoxGeometry(.15,2.7,.06),ink,g);strip.position.set(x,0,.1);}for(let i=0;i<5;i++){const line=w.mesh(new T.BoxGeometry(2.7-i%2*.7,.12,.04),ink,g);line.position.set(0,.9-i*.4,.1);}g.userData.originalTicket=true;return g;}
export function updateTicket(w,pose){const g=w.prop;if(!g||!pose)return;const v=w.ticketScratch??={a:new T.Vector3(),b:new T.Vector3(),q:new T.Quaternion(),tilt:new T.Quaternion(),axis:new T.Vector3(1,0,0)};w.player.updateMatrixWorld(true);w.player.userData.limbs[0].userData.grip.getWorldPosition(v.a);w.player.userData.limbs[1].userData.grip.getWorldPosition(v.b);g.position.copy(v.a).lerp(v.b,.5);w.player.getWorldQuaternion(v.q);v.tilt.setFromAxisAngle(v.axis,-.35+pose.lift*.2);g.quaternion.copy(v.q).multiply(v.tilt);g.visible=pose.reach>.02;}
